use strict; use warnings; use Math::Trig qw(pi);
sub signed_area { my($p,$q,$r)=@_; return ($q->[1]-$p->[1])*($r->[0]-$q->[0]) - ($q->[0]-$p->[0])*($r->[1]-$q->[1]); }
sub pit {
 my($ax,$ay,$bx,$by,$cx,$cy,$px,$py)=@_;
 return ($cx-$px)*($ay-$py) >= ($ax-$px)*($cy-$py)
     && ($ax-$px)*($by-$py) >= ($bx-$px)*($ay-$py)
     && ($bx-$px)*($cy-$py) >= ($cx-$px)*($by-$py);
}
sub triangulate {
 my($n)=@_; my $m=2*$n; my @p;
 for my $i (0..$m-1) { my $t=$i/$m; my $a=4*pi*$t; push @p,[$t*cos($a),$t*sin($a)]; }
 return () if $m<3;
 my(@next,@prev); $next[$_]=($_+1)%$m and $prev[$_]=($_-1+$m)%$m for 0..$m-1;
 my(@out,%live); $live{$_}=1 for 0..$m-1;
 my($ear,$stop,$first)=(0,0,0); my $pass=0;
 while ($pass || $ear != $stop) {
  my $pr=$prev[$ear]; my $nx=$next[$ear];
  my($a,$b,$c)=($p[$pr],$p[$ear],$p[$nx]);
  my $is=0;
  if (signed_area($a,$b,$c) < 0) {
   my($minx,$maxx)=sort {$a<=>$b} ($a->[0],$b->[0],$c->[0]);
   my($miny,$maxy)=sort {$a<=>$b} ($a->[1],$b->[1],$c->[1]);
   $is=1; my $q=$next[$ear];
   while($q != $pr) {
    my $v=$p[$q];
    if ($v->[0]>=$minx && $v->[0]<=$maxx && $v->[1]>=$miny && $v->[1]<=$maxy
       && pit($a->[0],$a->[1],$b->[0],$b->[1],$c->[0],$c->[1],$v->[0],$v->[1])
       && signed_area($p[$prev[$q]],$v,$p[$next[$q]]) >= 0) { $is=0; last; }
    $q=$next[$q];
   }
  }
  if($is) {
   push @out,$pr,$ear,$nx;
   $next[$pr]=$nx; $prev[$nx]=$pr; $next[$ear]=$prev[$ear]=$ear;
   $ear=$next[$nx]; $stop=$ear; next;
  }
  $ear=$next[$ear];
  if($ear==$stop){ last; } # no fallback modeled
 }
 return @out;
}
